    static T Field<T>(object instance,string name)=>(T)instance.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(instance)!;
    static IEnumerable<Control> Walk(Control root){foreach(Control c in root.Controls){yield return c;foreach(var nested in Walk(c))yield return nested;}}
    public static void Run(string report){try{var folder=Path.GetDirectoryName(report)!;Directory.CreateDirectory(folder);var checks=Check(folder);File.WriteAllText(report,JsonSerializer.Serialize(new{ok=checks.Values.All(x=>x),checks},new JsonSerializerOptions{WriteIndented=true}));}catch(Exception e){File.WriteAllText(report,JsonSerializer.Serialize(new{ok=false,error=e.ToString()}));}}
