        var c=new Dictionary<string,bool>();var executable=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"cmd.exe");var file=Path.Combine(folder,"a file & test.txt");File.WriteAllText(file,"fixture");var id=Guid.NewGuid().ToString("N");var app=new LocalApplication(id,"示例编辑器",executable,true,"","/d /c",folder,true);var current=new Preferences{ApplicationModules=[app],Favorites=["private fixture"],Aliases=new(){{"fixture",["test"]}},DisplayName="Test Leo",PetSize=137,ModuleExecutables=new(){{"terminal",executable}}};
        var templates=UsageProfiles.Templates();c["four_distinct_templates"]=templates.Length==4&&templates.Select(t=>t.Id).Distinct().Count()==4;foreach(var t in templates)UsageProfiles.Validate(t);
        var pure=UsageProfiles.Prepare(templates[0],current);c["companion_turns_off_optional_capabilities"]=EntryDisplay.Entries(pure).All(e=>!e.Enabled);c["companion_turns_off_background_sources"]=!pure.ApplicationIndexing&&!pure.ContextAware&&!pure.ClipboardHistory&&!pure.AutoUpdateNotifications;c["companion_has_no_voice_or_index_hotkeys"]=pure.SearchHotkey==Keys.None&&pure.VoiceHotkey==Keys.None&&pure.LyricsHotkey==Keys.None;c["switch_preserves_personal_preferences"]=pure.Favorites.SequenceEqual(current.Favorites)&&pure.DisplayName==current.DisplayName&&pure.PetSize==current.PetSize&&pure.ModuleExecutables.SequenceEqual(current.ModuleExecutables)&&pure.ApplicationModules[0].Arguments==app.Arguments;
        c["preparing_does_not_mutate_current"]=current.ApplicationIndexing&&current.ApplicationModules[0].Enabled;var mixed=UsageProfiles.Capture(current,"Mixed");var prepared=UsageProfiles.Prepare(mixed,pure);c["custom_scheme_restores_mixed_configuration"]=prepared.ApplicationModules[0].Enabled&&prepared.TerminalModule&&prepared.ApplicationIndexing;
        string json=UsageProfiles.Serialize(mixed);c["export_excludes_paths_and_records"]=!json.Contains(executable.Replace("\\","\\\\"))&&!json.Contains("private fixture")&&!json.Contains("Favorites")&&!json.Contains("ModuleExecutables")&&!json.Contains("EncryptedKey")&&!json.Contains("WorkingDirectory");var export=Path.Combine(folder,"profile.json");File.WriteAllText(export,json);var imported=UsageProfiles.Import(export);c["import_gives_independent_id"]=imported.Id!=mixed.Id&&imported.Modules.SequenceEqual(mixed.Modules);c["import_is_passive"]=current.ActiveProfile.Length==0;
        File.WriteAllText(export,json[..^1]+",\"EncryptedKey\":\"forbidden\"}");try{UsageProfiles.Import(export);c["unknown_import_fields_rejected"]=false;}catch(JsonException){c["unknown_import_fields_rejected"]=true;}File.WriteAllText(export,json);
        var storePath=Path.Combine(folder,"profiles.json");if(File.Exists(storePath))File.Delete(storePath);var store=new ProfileStore(storePath);store.Save(mixed);c["profile_persists"]=new ProfileStore(storePath).Items.Single().Name=="Mixed";store.Save(mixed with{Name="Renamed"});c["rename_does_not_duplicate"]=store.Items.Count==1&&store.Items[0].Name=="Renamed";store.Delete(mixed.Id);c["delete_only_removes_scheme"]=store.Items.Count==0&&current.ApplicationModules.Count==1;
        int applications=0;bool original=current.ApplicationIndexing;try{ProfileTransition.Apply(current,pure,next=>{applications++;current.ApplicationIndexing=next.ApplicationIndexing;if(applications==1)throw new IOException("fixture failure");});}catch(IOException){}c["failed_switch_rolls_back"]=applications==2&&current.ApplicationIndexing==original;
        var foreign=mixed with{Modules=new(){{"foreign-id",true}}};c["profile_preview_preserves_line_breaks"]=UsageProfiles.Describe(mixed,current).Contains(Environment.NewLine+"搜索快捷键");c["missing_module_is_explained"]=UsageProfiles.Describe(foreign,current).Contains("未匹配的模块");c["foreign_scheme_does_not_install_app"]=UsageProfiles.Prepare(foreign,current).ApplicationModules.Count==1;
        var start=FileDropActions.ConfiguredStart(current,id,[file]);c["drop_preserves_flags_and_directory"]=start.Verb=="runas"&&start.WorkingDirectory==folder&&start.UseShellExecute;c["drop_preserves_parameters_and_quotes_paths"]=start.Arguments==app.Arguments+" "+FileDropActions.QuoteArgument(file);c["quoted_trailing_slash_is_escaped"]=FileDropActions.QuoteArgument("C:\\some folder\\")=="\"C:\\some folder\\\\\"";current.ApplicationModules[0]=app with{Enabled=false};try{FileDropActions.ConfiguredStart(current,id,[file]);c["drop_rejects_disabled_module"]=false;}catch(InvalidOperationException){c["drop_rejects_disabled_module"]=true;}current.ApplicationModules[0]=app;
        using(var editor=new QuickEntrySettingsForm(current,id)){c["custom_button_has_config_and_display_controls"]=Walk(editor).OfType<Button>().Any(b=>b.Text=="编辑模块配置…")&&Walk(editor).OfType<ComboBox>().Single().Items.Count==3;c["entry_editor_is_draft_only"]=!ReferenceEquals(editor.Result,current)&&editor.Result.ApplicationModules[0]==app;}
        using(var button=new Button()){string managed="";ShortcutManagement.Wire(button,id,key=>managed=key);((ToolStripMenuItem)button.ContextMenuStrip!.Items[0]).PerformClick();c["button_context_targets_correct_module"]=managed==id;}
        using(var pet=new PetForm(pure,true)){pet.Show();Application.DoEvents();var launcher=Field<LauncherForm>(pet,"launcher");c["companion_does_not_start_catalog_worker"]=!Field<bool>(launcher,"catalogStarted");c["companion_stops_observer"]=!Field<System.Windows.Forms.Timer>(launcher,"observer").Enabled;var foot=Field<FootTools>(pet,"foot");c["companion_stops_proxy_polling"]=!Field<System.Windows.Forms.Timer>(foot,"proxyTimer").Enabled;pet.ApplyPlatformSettings(UsageProfiles.Prepare(templates[3],pure));c["scheme_apply_updates_actual_preferences"]=pure.FootballModule&&pure.MusicModule&&pure.ApplicationIndexing;pet.ApplyPlatformSettings(UsageProfiles.Prepare(templates[0],pure));c["switch_back_cancels_catalog_and_stops_observer"]=!Field<bool>(launcher,"catalogStarted")&&!Field<System.Windows.Forms.Timer>(launcher,"observer").Enabled;pet.Close();}Modules.SetFootball(true);
        using(var clipboard=new ClipboardHistoryService(pure,true)){c["disabled_clipboard_has_no_timer"]=!Field<System.Windows.Forms.Timer>(clipboard,"timer").Enabled;}
        using(var form=new UsageProfilesForm(current,_=>{},true)){form.StartPosition=FormStartPosition.Manual;form.Location=new(-19000,-19000);form.Show();Application.DoEvents();using var image=new Bitmap(form.Width,form.Height);form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(folder,"usage-profiles.png"));c["scheme_ui_has_all_four_templates"]=Walk(form).OfType<ListBox>().Single().Items.Count==4;form.Close();}
        var resourceChecks=Task.Run(async()=>{var hub=new ClientOperationHub(_=>{});bool cancelHeldGate=false;var entered=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var task=hub.Run("music","wait",async op=>{using var registration=op.Token.Register(()=>cancelHeldGate=Monitor.IsEntered(Field<object>(hub,"gate")));entered.SetResult();await Task.Delay(Timeout.Infinite,op.Token);return "unexpected";});await entered.Task;hub.Configure("music",false);bool cancelled=false,blocked=false;try{await task;}catch(OperationCanceledException){cancelled=true;}try{await hub.Run("music","blocked",_=>Task.FromResult("unexpected"));}catch(InvalidOperationException){blocked=true;}hub.Configure("music",true);bool restored=await hub.Run("music","restored",_=>Task.FromResult("ok"))=="ok";return (cancelled,blocked,restored,cancelHeldGate);}).GetAwaiter().GetResult();c["disabling_module_cancels_waiting_client_operation"]=resourceChecks.cancelled&&!resourceChecks.cancelHeldGate;c["disabled_resource_rejects_stale_window_request"]=resourceChecks.blocked;c["reenabled_resource_accepts_new_operation"]=resourceChecks.restored;
        using(var dock=new DockSprites()){bool proportions=true;for(int i=0;i<24;i++){var side=(DockSide)(i/6+1);var source=dock.Source((i%6)/5f,0,side);var size=new Size(192,208);var target=dock.Destination(size,1,side,source);var head=dock.HeadAt(i);proportions&=head.Width*target.Width/source.Width<=dock.ReferenceHead.Width*.9f&&head.Height*target.Height/source.Height<=dock.ReferenceHead.Height*.9f;}c["all_tucked_heads_are_smaller_than_standing_head"]=proportions;}
        File.Delete(file);return c;
    }
